const raw = $json.choices?.[0]?.message?.content;
if (!raw) { throw new Error('Empty LLM response'); }
let parsed;
try { parsed = JSON.parse(raw); }
catch (e) { const m = raw.match(/\{[\s\S]*\}/); if (m) { parsed = JSON.parse(m[0]); } else { throw new Error('LLM did not return JSON: ' + raw.slice(0, 300)); } }
const list = Array.isArray(parsed) ? parsed : (Array.isArray(parsed.candidates) ? parsed.candidates : []);
if (!list.length) { throw new Error('No candidates in LLM response'); }
const allowed = ['engineering', 'data', 'design', 'operations', 'sales', 'support', 'management', 'other'];
const out = [];
for (const c of list) {
  const category = allowed.includes(String(c.category || '').toLowerCase()) ? String(c.category).toLowerCase() : 'other';
  const confidence = Math.round(Math.min(1, Math.max(0, Number(c.confidence) || 0)) * 1000) / 1000;
  const reason = String(c.reason || '').replace(/[\r\n]+/g, ' ').replace(/'/g, "''").slice(0, 500);
  out.push({ json: { personId: Number(c.id), category, confidence, reason } });
}
return out;
